package com.bank.sqli;

import java.sql.*;
import java.util.*;
import java.util.logging.*;

public class SqlInjectionDemo {
    private static final Logger log = Logger.getLogger(SqlInjectionDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        Connection conn = DriverManager.getConnection("jdbc:h2:mem:bankdb;DB_CLOSE_DELAY=-1");
        try (Statement s = conn.createStatement()) {
            s.execute("CREATE TABLE accounts (id VARCHAR(20) PRIMARY KEY, owner VARCHAR(100), balance DECIMAL(15,2))");
            s.execute("INSERT INTO accounts VALUES ('SAV2001','Rajesh Kumar',1000000.00),('CUR3001','Priya Sharma',250000.00)");
        }
        AccountRepository repo = new AccountRepository(conn);

        String maliciousInput = "' OR '1'='1";

        // VULNERABLE: concatenation lets input become code.
        List<Account> leaked = repo.findByOwnerVulnerable(maliciousInput);
        log.severe("VULNERABLE query returned " + leaked.size()
            + " rows for malicious input -> DATA LEAK: " + leaked);

        // SAFE: parameterized query treats input as data only.
        List<Account> safe = repo.findByOwnerSafe(maliciousInput);
        log.info("SAFE parameterized query returned " + safe.size()
            + " rows for the same malicious input -> attack neutralized");

        // SAFE query still works for legitimate input.
        List<Account> real = repo.findByOwnerSafe("Rajesh Kumar");
        log.info(() -> "SAFE query for 'Rajesh Kumar' returned: " + real);
    }
}

