class Account {
    final String id; final String owner; final java.math.BigDecimal balance;
    Account(String id, String owner, java.math.BigDecimal balance) {
        this.id = id; this.owner = owner; this.balance = balance;
    }
    @Override public String toString() { return id + "(" + owner + ")"; }
}

// ─── Would be in AccountRepository.java ───
class AccountRepository {
    private final Connection conn;
    AccountRepository(Connection conn) { this.conn = conn; }

    // NEVER DO THIS — concatenation enables SQL injection.
    List<Account> findByOwnerVulnerable(String owner) throws SQLException {
        String sql = "SELECT id, owner, balance FROM accounts WHERE owner = '" + owner + "'";
        try (Statement st = conn.createStatement(); ResultSet rs = st.executeQuery(sql)) {
            return map(rs);
        }
    }

    // DO THIS — parameter binding: structure fixed, value is pure data.
    List<Account> findByOwnerSafe(String owner) throws SQLException {
        String sql = "SELECT id, owner, balance FROM accounts WHERE owner = ?";
        try (PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setString(1, owner);
            try (ResultSet rs = ps.executeQuery()) { return map(rs); }
        }
    }

    private List<Account> map(ResultSet rs) throws SQLException {
        List<Account> out = new ArrayList<>();
        while (rs.next())
            out.add(new Account(rs.getString("id"), rs.getString("owner"), rs.getBigDecimal("balance")));
        return out;
    }
}

